using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CreatedCampaignTests
{
    static WorldSession New(long until=long.MaxValue)=>new(CreatedCampaign.Create(commandUntil:until));
    static void Advance(WorldSession s,long at){s.SetPaused(false);Assert.Equal(at,s.AdvanceTo(at).ReachedAt);}
    static void Open(WorldSession s){Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,RegionalWork.Inbox(s).Single(c=>c.CanOpen).Message,s.Revision).Code);}
    static void FinishWork(WorldSession s){if(s.Seconds<2)Advance(s,2);if(RegionalWork.Inbox(s).Any(c=>c.CanOpen))Open(s);if(s.Seconds<9)Advance(s,9);}
    static void Deploy(WorldSession s)=>Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);
    static RegionalRequest Order(WorldSession s,string id,RegionalAction action=RegionalAction.Move)=>new(new(id),s.PlayerControl,s.PlayerControl,action,ContinuousWorld.Point("castle",65000,-85000),ContinuousWorld.Point("castle",85000,-85000));
    static void Issue(WorldSession s,string id,RegionalAction action=RegionalAction.Move)=>Assert.Equal(ResultCode.Accepted,s.IssueRegional(Order(s,id,action),s.Revision).Code);
    static long End(WorldSession s)=>s.DiagnosticSnapshot().Region!.Units.Where(u=>u.Commander==s.PlayerControl).SelectMany(u=>u.Route).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max();
    static void Return(WorldSession s){Issue(s,"request:return/"+s.Revision,RegionalAction.Retreat);Advance(s,End(s)+1);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(false,s.Revision).Code);}
    static WorldSession Restore(WorldSession s){s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"created-campaign-"+Guid.NewGuid().ToString("N")),s.DiagnosticSnapshot().Definitions);store.Save(s,"case",s.DiagnosticSnapshot().WorldId,new(0,1));var host=new WorldSessionHost(new WorldSession(CreatedCampaign.Create()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));return host.Current;}
    [Fact] public void ArmyIsHousePropertyWithExplicitLimitedMandate(){var w=CreatedCampaign.Create();Assert.Single(w.CommandMandates!);Assert.Equal(RetainerStart.Lord,w.Definitions.Armies.Single(a=>a.Id==CreatedCampaign.Army).Commander);Assert.All(w.Units.Where(u=>u.Commander==w.PlayerControl),u=>Assert.Equal(RetainerStart.House,u.Organization));Assert.DoesNotContain(w.ResourceLots,l=>l.Owner==w.PlayerControl);Assert.Equal(100L,StartConfiguration.Check(w,StartConfiguration.Describe(w,w.PlayerControl,StartTemplate.Retainer,PersonOrigin.Created,CreatedCampaign.Policy),CreatedCampaign.Policy).CreationCost);}
    [Fact] public void RankWithoutMandateStillCannotDeploy(){var s=new WorldSession(RetainerStart.Create());Assert.Equal(ResultCode.NotAvailable,s.SetRegionalActive(true,s.Revision).Code);var w=CreatedCampaign.Create();w.CommandMandates=null;Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact] public void PlayerAndTroopsMoveWithoutMovingFormerFixtureOfficer(){var s=New();var original=s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==ContractFixture.Officer);Deploy(s);Issue(s,"request:line");Advance(s,20);var w=s.DiagnosticSnapshot();Assert.NotEqual(w.Region!.Units[0].Home,w.Region.Units[0].Position);Assert.Equal(original,w.Locations.Single(l=>l.Actor==ContractFixture.Officer));Assert.Contains(s.PlayerControl,RegionalBattle.Commanders(w));Assert.DoesNotContain(ContractFixture.Officer,RegionalBattle.Commanders(w));}
    [Fact] public void MovementHoldAndReturnDoNotGrantEngageOrAllyCommand(){var s=New();Deploy(s);Issue(s,"request:hold",RegionalAction.Hold);string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.IssueRegional(Order(s,"request:engage",RegionalAction.Engage),s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.IssueRegional(Order(s,"request:ally") with{Recipient=ContractFixture.Clerk},s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact] public void PeaceDeploymentAndGarrisonRetainTheSameWorldAndClock(){var s=New();var id=s.DiagnosticSnapshot().WorldId;FinishWork(s);long at=s.Seconds;Deploy(s);Issue(s,"request:line");Advance(s,End(s)+1);Return(s);Assert.False(s.DiagnosticSnapshot().Region!.Active);Assert.Equal(id,s.DiagnosticSnapshot().WorldId);Assert.True(s.Seconds>at);Assert.Equal(ContractFixture.Castle,s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==s.PlayerControl).Site);Advance(s,3602);Open(s);Advance(s,3609);Assert.Equal(2,s.DiagnosticSnapshot().Tasks.Count(t=>t.Action==ActionKind.Inspect&&t.Execution==ExecutionPhase.Completed));}
    [Fact] public void SoloTravelCannotTeleportGarrisonTroops(){var s=New();var before=ContractJson.Write(s.DiagnosticSnapshot().Region!.Units);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:solo","kofu"),s.Revision).Code);Advance(s,1);long at=s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs[^1].EndAt;Advance(s,at);Assert.Equal(ResultCode.NotAvailable,s.SetRegionalActive(true,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot().Region!.Units));}
    [Fact] public void ExpiryBlocksNewPlacementButAllowsSafeReturn(){var s=New(5);Deploy(s);Issue(s,"request:line");Advance(s,6);var late=s.IssueRegional(Order(s,"request:late"),s.Revision);Assert.True(late.Code==ResultCode.NotAvailable,"late order code "+late.Code+" time "+s.Seconds+" until "+s.DiagnosticSnapshot().CommandMandates![0].Until);Return(s);var redeploy=s.SetRegionalActive(true,s.Revision);Assert.True(redeploy.Code==ResultCode.NotAvailable,"redeploy code "+redeploy.Code+" time "+s.Seconds+" until "+s.DiagnosticSnapshot().CommandMandates![0].Until);}
    [Fact] public void SourceSnapshotSurvivesSameTickDispatchAndDeployment(){var s=New();Advance(s,2);Open(s);Assert.Equal(ResultCode.Accepted,s.InterruptMission(s.DiagnosticSnapshot().Tasks.Single().Id,s.PlayerControl,s.Revision).Code);Advance(s,3);Assert.Equal(ResultCode.Accepted,s.ExplainMission(s.DiagnosticSnapshot().Tasks.Single().Id,s.PlayerControl,MissionReview.Explanation.OwnDecision,s.Revision).Code);var source=s.DiagnosticSnapshot().Couriers!.Missions.Last().Origin;Deploy(s);var w=s.DiagnosticSnapshot();Assert.Equal(source,w.Couriers!.Missions.Last().Origin);Assert.Equal(LocationKind.AtSite,w.Couriers.Missions.Last().DispatchPose!.Location.Kind);Advance(s,4);Assert.Contains("自己判断",MissionReview.View(s,RetainerStart.Lord).Single().Reason);Return(s);ContractValidation.Validate(s.DiagnosticSnapshot());}
    [Fact] public void FieldReasonUsesPhysicalFirstMileAndSurvivesReturn(){var s=New();Advance(s,2);Open(s);s.InterruptMission(s.DiagnosticSnapshot().Tasks.Single().Id,s.PlayerControl,s.Revision);Advance(s,3);Deploy(s);Assert.Equal(ResultCode.Accepted,s.ExplainMission(s.DiagnosticSnapshot().Tasks.Single().Id,s.PlayerControl,MissionReview.Explanation.OwnDecision,s.Revision).Code);var mission=s.DiagnosticSnapshot().Couriers!.Missions.Last();Assert.NotEmpty(mission.FirstMile!);Assert.Equal(LocationKind.AtPosition,mission.DispatchPose!.Location.Kind);var copy=Restore(s);Return(s);Return(copy);Advance(s,Math.Max(s.Seconds,mission.ReadyAt)+1);Advance(copy,Math.Max(copy.Seconds,mission.ReadyAt)+1);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(copy.DiagnosticSnapshot()));Assert.Contains("自己判断",MissionReview.View(s,RetainerStart.Lord).Single().Reason);}

    [Fact] public void LiteralOldInitialAndSavedWorldsStillReadWithoutNewFields(){foreach(var name in new[]{"initial","saved"}){var bytes=File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","created-ronin-bea3d4f-"+name+".json"));var w=ContractJson.Read<ContractWorld>(bytes);ContractValidation.Validate(w);Assert.Null(w.CommandMandates);if(name=="initial")Assert.Equal("a5587a8d1bba2cf0a68ee104f41b6b23247abb1c2217876eeefe045fd76ac8bf",ContractJson.CanonicalHash(w));else Assert.Equal(bytes,ContractJson.Write(w));Assert.Equal(PersonalStart.Create("検証浪人").Definitions.Version,w.Definitions.Version);new WorldSession(w);}}
    [Theory][InlineData("agent")][InlineData("army")][InlineData("unit")][InlineData("action")][InlineData("from")][InlineData("basis")]
    public void InvalidMandatesCannotLoad(string kind){var w=CreatedCampaign.Create();var m=w.CommandMandates![0];w.CommandMandates[0]=kind switch{"agent"=>m with{Agent=ContractFixture.Clerk},"army"=>m with{Army=new("army:absent")},"unit"=>m with{Units=[new("unit:absent")]},"action"=>m with{Actions=[RegionalAction.Engage]},"from"=>m with{From=1},_=>m with{Basis=new("basis:service")}};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]
    public void FormationAndReturnRestoreExactState(int step){var s=New();FinishWork(s);if(step>0)Deploy(s);if(step>1){Issue(s,"request:line");Advance(s,20);}if(step>2){Issue(s,"request:back",RegionalAction.Retreat);Advance(s,25);}if(step>3){Advance(s,End(s)+1);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(false,s.Revision).Code);}var restored=Restore(s);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));if(s.DiagnosticSnapshot().Region!.Active){Return(s);Return(restored);}else{Deploy(s);Deploy(restored);Return(s);Return(restored);}Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));}
    [Theory][InlineData("at")][InlineData("actor")][InlineData("site")][InlineData("shape")][InlineData("missing")]
    public void InvalidDispatchProvenanceIsRejected(string kind){var s=New();Advance(s,1);var w=s.DiagnosticSnapshot();var c=w.Couriers!.Missions.Single();var pose=c.DispatchPose!;w.Couriers.Missions[0]=c with{DispatchPose=kind switch{"at"=>pose with{At=pose.At+1},"actor"=>pose with{Location=pose.Location with{Actor=ContractFixture.Clerk}},"site"=>pose with{Location=pose.Location with{Site=new("site:kofu")}},"shape"=>pose with{Location=pose.Location with{HeightMm=1}},_=>null}};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact] public void OldProfilesRejectAnInjectedCommandModule(){var w=RetainerStart.Create();w.CommandMandates=[];Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact] public void RegionAndUnitCommandersCannotDisagree(){var w=CreatedCampaign.Create();w.Region!.Units[0]=w.Region.Units[0] with{Commander=ContractFixture.Officer};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Theory][InlineData("person:created/alpha")][InlineData("person:commander/alternate")][InlineData("person:synthetic-officer")]
    public void ExistingFixtureExecutionDoesNotDependOnOfficerLiteral(string id){var w=ContinuousWorld.Create();var node=System.Text.Json.Nodes.JsonNode.Parse(ContractJson.Write(w))!;void Rename(System.Text.Json.Nodes.JsonNode n){if(n is System.Text.Json.Nodes.JsonObject o){foreach(var key in o.Select(p=>p.Key).ToArray()){if(o[key] is System.Text.Json.Nodes.JsonValue v&&v.TryGetValue<string>(out var value)&&value==ContractFixture.Officer.Value)o[key]=id;else if(o[key]!=null)Rename(o[key]!);}}else if(n is System.Text.Json.Nodes.JsonArray a)foreach(var child in a)if(child!=null)Rename(child);}Rename(node);w=ContractJson.Read<ContractWorld>(System.Text.Encoding.UTF8.GetBytes(node.ToJsonString()));var s=new WorldSession(w);Assert.Equal(new EntityId(id),s.PlayerControl);Issue(s,"request:alias");Advance(s,10);var group=s.DiagnosticSnapshot().Region!.Units.Where(u=>u.Commander==s.PlayerControl).ToArray();Assert.Equal(3,group.Length);Assert.Contains(group,u=>u.Position!=u.Home);Assert.All(group,u=>Assert.Equal(new EntityId(id),u.Commander));ContractValidation.Validate(s.DiagnosticSnapshot());}
    [Fact] public void UnknownMailNeitherLocksDeploymentNorInventsExecutorReport(){var s=New();Advance(s,1);Assert.Empty(s.GetActorView(s.PlayerControl).Tasks);Deploy(s);Advance(s,70);Assert.Empty(s.GetActorView(s.PlayerControl).Tasks);Assert.DoesNotContain(s.DiagnosticSnapshot().Messaging.Messages,m=>m.SenderId==s.PlayerControl.Value&&m.Kind=="contract-report");}
    [Fact] public void OpenedFieldOrderWaitsForGarrisonWithoutStartingAtWrongSite(){var s=New();Advance(s,2);Deploy(s);Open(s);Assert.Equal(ExecutionPhase.Waiting,s.DiagnosticSnapshot().Tasks.Single().Execution);Advance(s,5);Return(s);long back=s.Seconds;Assert.Equal(ExecutionPhase.Running,s.DiagnosticSnapshot().Tasks.Single().Execution);Advance(s,back+5);Assert.Equal(ExecutionPhase.Completed,s.DiagnosticSnapshot().Tasks.Single().Execution);}
    [Fact] public void FieldExpiryReportTakesActualTimeToReachLord(){var s=New();Advance(s,2);Deploy(s);Open(s);Advance(s,62);var report=s.DiagnosticSnapshot().Couriers!.Missions.Last();Assert.NotEmpty(report.FirstMile!);Assert.True(report.ReadyAt>62);Assert.False(NpcWork.Inputs(s.DiagnosticSnapshot(),RetainerStart.Lord,s.Seconds).LastReportKnown);Advance(s,report.ReadyAt-1);Assert.False(NpcWork.Inputs(s.DiagnosticSnapshot(),RetainerStart.Lord,s.Seconds).LastReportKnown);Advance(s,report.ReadyAt);Assert.True(NpcWork.Inputs(s.DiagnosticSnapshot(),RetainerStart.Lord,s.Seconds).LastReportKnown);}
    [Theory][InlineData("speed")][InlineData("endpoint")][InlineData("start")]
    public void FirstMileGeometryAndChronologyCannotBeForged(string change){var s=New();Advance(s,2);Open(s);s.InterruptMission(s.DiagnosticSnapshot().Tasks.Single().Id,s.PlayerControl,s.Revision);Advance(s,3);Deploy(s);s.ExplainMission(s.DiagnosticSnapshot().Tasks.Single().Id,s.PlayerControl,MissionReview.Explanation.OwnDecision,s.Revision);var w=s.DiagnosticSnapshot();var c=w.Couriers!.Missions.Last();Assert.NotEmpty(c.FirstMile!);c.FirstMile![0]=change switch{"speed"=>c.FirstMile[0] with{Speed=9999},"endpoint"=>c.FirstMile[0] with{To=new(123,456)},_=>c.FirstMile[0] with{StartAt=c.FirstMile[0].StartAt+1}};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}

}
